values ((select s.id from public.sessions s join public.topics t on t.id = s.topic_id where t.slug = 'prompt-engineering' and s.order_index = 1),
  'Which prompt is most likely to give a useful answer?', '["\"Tell me about churn.\"","\"Churn?\"","\"Write something about customers.\"","\"As an analyst at a subscription company, list five reasons customers cancel as a table with a suggested fix for each.\""]'::jsonb, 3, 'It gives context, a clear task and a format. The others leave the model guessing.', 1);
insert into public.inline_quizzes (session_id, question, options, correct_index, explanation, order_index)
